const q = String($('POST /ask-agent').first().json.body?.question ?? '').trim();
const SYSTEM = 'You are an ops research assistant for a quake-alert service. Answer the user using the tools. Call at most ONE tool per turn. Never invent data: if the tools cannot answer, say so with can_answer=false. You cannot send email. Use draft_email only when the user asks you to prepare a message; a human must approve it before anything is sent. When you are done, reply with ONLY JSON: {"can_answer": boolean, "answer": string (max 1200 chars), "sources": [string]}.';
const TOOLS = [
  { name: 'get_recent_quakes', description: 'Strongest recent earthquakes from the USGS public API.', input_schema: { type: 'object', properties: { region: { type: 'string', enum: ['philippines', 'japan', 'worldwide'] }, min_magnitude: { type: 'number' }, days: { type: 'integer', minimum: 1, maximum: 7 } }, required: ['region'] } },
  { name: 'lookup_client', description: 'Look up a client config row (region, threshold, tone, enabled) by client_id.', input_schema: { type: 'object', properties: { client_id: { type: 'string' } }, required: ['client_id'] } },
  { name: 'draft_email', description: 'Save an email DRAFT for human approval. Does not send.', input_schema: { type: 'object', properties: { to: { type: 'string' }, subject: { type: 'string' }, body: { type: 'string' } }, required: ['to', 'subject', 'body'] } }
];
const cfg = $('Agent Limits').first().json;
return [{ json: { state: { question: q, system: SYSTEM, tools: TOOLS, messages: [{ role: 'user', content: q }], iter: 0, tokens_in: 0, tokens_out: 0, started_ms: Date.now(), limits: cfg, trace: [], draft: null } } }];

// Copy the state carried by the request that produced this response (the HTTP node replaces $json).
const s = JSON.parse(JSON.stringify($('Build Claude Request').item.json.state));
const r = $json;
if (r.error || !Array.isArray(r.content)) {
  return { json: { state: s, next: 'error', limit_reason: '', error: String(r.error?.message ?? 'Bad response from model').slice(0, 300) } };
}
s.iter += 1;
s.tokens_in += r.usage?.input_tokens ?? 0;
s.tokens_out += r.usage?.output_tokens ?? 0;
s.messages.push({ role: 'assistant', content: r.content });
const calls = r.content.filter(c => c.type === 'tool_use');
const total = s.tokens_in + s.tokens_out;
const elapsed = (Date.now() - s.started_ms) / 1000;
s.trace.push({ iter: s.iter, stop: r.stop_reason, tool: calls[0]?.name ?? null, tokens: total });
let next = 'final', limit_reason = '';
if (r.stop_reason === 'tool_use' && calls.length) {
  // Hard limits are checked before any further tool call or model turn.
  if (s.iter >= s.limits.max_iterations) limit_reason = 'max_iterations (' + s.limits.max_iterations + ')';
  else if (total >= s.limits.token_budget) limit_reason = 'token_budget (' + total + '/' + s.limits.token_budget + ')';
  else if (elapsed >= s.limits.timeout_seconds) limit_reason = 'timeout (' + Math.round(elapsed) + 's)';
  next = limit_reason ? 'limit' : 'tool';
}
return { json: { state: s, next, limit_reason, error: '', tool_call: calls[0] ?? null, skipped: calls.slice(1).map(c => c.id) } };

const p = $('Process Response').item.json;
const s = JSON.parse(JSON.stringify(p.state));
if (p.tool_call.name === 'draft_email') s.draft = p.tool_call.input;
const results = [{ type: 'tool_result', tool_use_id: p.tool_call.id, content: String($json.content ?? '').slice(0, 4000) }]
  .concat(p.skipped.map(id => ({ type: 'tool_result', tool_use_id: id, content: 'Skipped: call one tool per turn.' })));
s.messages.push({ role: 'user', content: results });
return { json: { state: s } };

const s = $json.state;
const last = s.messages[s.messages.length - 1];
const text = (last.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let p = null, error = null;
try { p = JSON.parse(text); } catch (e) { error = 'not_json'; }
if (!error) {
  if (typeof p.can_answer !== 'boolean') error = 'bad_can_answer';
  else if (typeof p.answer !== 'string' || !p.answer.trim() || p.answer.length > 1500) error = 'bad_answer';
  else if (!Array.isArray(p.sources)) error = 'bad_sources';
}
const status = error ? 'invalid_output' : (p.can_answer ? 'answered' : 'cannot_answer');
return { json: { state: s, status, error, limit_reason: '', answer: error ? text.slice(0, 500) : p.answer, sources: error ? [] : p.sources, draft: s.draft } };
